INSERT INTO `daotao_chuandaura` VALUES (1, 'PLO1 (3K)', 'Ứng dụng các kiến thức cơ bản về khoa học tự nhiên, khoa học xã hội, khoa học chính trị, và y học cơ sở liên quan để giải quyết các vấn đề thuộc lĩnh vực khoa học sức khỏe.', 'KT', '2025-05-31 05:26:38.983802', '2025-05-31 05:27:08.557899', 2);
INSERT INTO `daotao_chuandaura` VALUES (2, 'PLO2 (3K)', 'Ứng dụng kiến thức chuyên ngành xét nghiệm để cung cấp các thông tin hữu ích cho các khoa lâm sàng trong chẩn đoán, điều trị và dự báo dịch bệnh, sức khỏe cộng đồng.', 'KT', '2025-05-31 05:27:41.870000', '2025-05-31 05:27:41.870000', 2);
INSERT INTO `daotao_chuandaura` VALUES (3, 'PLO3 (5K)', 'Đánh giá đúng kết quả xét nghiệm dựa trên kiến thức chuyên môn về: hóa sinh, miễn dịch, huyết học- truyền máu, vi sinh, ký sinh trùng, xét nghiệm tế bào, sinh học phân tử.', 'KT', '2025-05-31 05:28:18.498702', '2025-05-31 05:28:18.498702', 2);
INSERT INTO `daotao_chuandaura` VALUES (4, 'PLO4 (4K)', 'Quản lý phòng xét nghiệm hoạt động an toàn, và thực hiện được các biện pháp đảm bảo chất lượng xét nghiệm.', 'KT', '2025-05-31 05:28:53.635143', '2025-05-31 05:28:53.635143', 2);
INSERT INTO `daotao_chuandaura` VALUES (5, 'PLO5 (4S)', 'Giám sát quy trình sử dụng hóa chất, sinh phẩm, quy trình vận hành, bảo dưỡng một số loại trang thiết bị chuyên dụng dùng trong phòng xét nghiệm y học.', 'KN', '2025-05-31 05:29:21.211857', '2025-05-31 05:29:21.211857', 2);
INSERT INTO `daotao_chuandaura` VALUES (6, 'PLO6 (4S)', 'Thực hiện thành thạo các kỹ thuật xét nghiệm thông thường, các xét nghiệm hàng loạt tại cộng đồng và một số các kỹ thuật chuyên sâu.', 'KN', '2025-05-31 05:29:58.169854', '2025-05-31 05:29:58.169854', 2);
INSERT INTO `daotao_chuandaura` VALUES (7, 'PLO7 (4S)', 'Sử dụng thành thạo công nghệ thông tin và kiến thức ngoại ngữ bậc 3/6 khung năng lực ngoại ngữ của Việt Nam  trong thực hành nghề nghiệp và nghiên cứu khoa học.', 'KN', '2025-05-31 05:30:38.248035', '2025-05-31 05:30:38.248035', 2);
INSERT INTO `daotao_chuandaura` VALUES (8, 'PLO8 (5S)', 'Xử lý các tình huống liên quan đến nghề nghiệp bằng phương pháp tư duy phản biện và khoa học.', 'KN', '2025-05-31 05:53:48.479970', '2025-05-31 05:53:48.479970', 2);
INSERT INTO `daotao_chuandaura` VALUES (9, 'PLO9 (4S)', 'Giao tiếp tốt với đồng nghiệp, bệnh nhân và cộng đồng.', 'KN', '2025-05-31 05:53:48.482976', '2025-05-31 05:53:48.482976', 2);
INSERT INTO `daotao_chuandaura` VALUES (10, 'PLO10 (4S)', 'Làm việc độc lập, hoặc phối hợp với đồng nghiệp và những đối tượng có liên quan trong hoạt động chuyên môn hay khi tham gia công tác chỉ đạo tuyến, phòng chống dịch.', 'KN', '2025-05-31 05:53:48.485975', '2025-05-31 05:53:48.485975', 2);
INSERT INTO `daotao_chuandaura` VALUES (11, 'PLO11 (4A)', 'Chấp hành quy định của pháp luật, tuân thủ đạo đức nghề nghiệp, giữ gìn y đức và thực thi trách nhiệm với xã hội.', 'TD', '2025-05-31 05:53:48.488482', '2025-05-31 05:53:48.488482', 2);
INSERT INTO `daotao_chuandaura` VALUES (12, 'PLO12 (4A)', 'Thể hiện tác phong làm việc chuyên nghiệp, có ý thức tự định hướng, có động cơ khởi nghiệp và học tập suốt đời.', 'TD', '2025-05-31 05:53:48.491498', '2025-05-31 05:53:48.491498', 2);
INSERT INTO `daotao_chuandaura` VALUES (13, 'CDR-7510605-001', 'Miêu tả quy trình quản lý hàng chuẩn.', 'KT', '2025-07-23 01:31:46.426679', '2025-07-23 01:31:46.426679', 53);
INSERT INTO `daotao_chuandaura` VALUES (14, 'PLO1', 'Áp dụng kiến thức về khoa học cơ bản, khoa học chính trị, pháp luật, công nghệ thông tin, ngoại ngữ vào hoạt động nghề nghiệp.', NULL, '2025-07-23 07:02:28.767091', '2025-07-23 07:02:28.767091', 106);
