INSERT INTO `daotao_chuongtrinhdaotao` VALUES (2, '7720601.2024.XNYH', 'Kỹ thuật xét nghiệm y học', 'DH', 'CQ', '4', '', '2025-05-31 04:43:05.408971', '2025-07-16 01:23:39.980650', 18, '- Chuẩn đầu ra CTĐT ngành Kỹ thuật Xét nghiệm y học Đại học Y Dược Thành phố Hồ Chí Minh.\r\n- Chuẩn đầu ra CTĐT ngành Kỹ thuật Xét nghiệm y học Trường Đại học Y Dược Cần Thơ đạt chuẩn kiểm định chất lượng giáo dục theo quy định của Bộ Giáo dục và Đào tạo năm 2021.\r\n- Chuẩn đầu ra CTĐT Bacherlor of Science in Medical Technology của Trường Đại học Mahidol, Thái Lan.\r\n- Chuẩn đầu ra CTĐT Bacherlor of Biomedical Science (Laboratory Medicine) của Trường Đại học RMIT, Úc.', 'Theo Quy định của Bộ Giáo dục và Đào tạo và Quy định của Trường Đại học Trà Vinh', 'Theo Quy định của Bộ Giáo dục và Đào tạo và Quy định của Trường Đại học Trà Vinh', 25, 140, 'Medical Laboratory Technology', 'CN', '', NULL, 'DRAFT', '1.0', NULL, NULL, NULL);
