INSERT INTO `daotao_hocphan` VALUES (1, '180050', 'Triết học Mác - Lênin', '2025-05-28 10:29:05.200000', '2025-07-23 03:09:56.409834', 'Học phần trang bị kiến thức về được những vấn đề cơ bản của triết học và vai trò của triết học trong đời sống xã hội nói chung, triết học Mác – Lênin nói riêng. Phân tích được những nội dung cơ bản của chủ nghĩa duy vật biện chứng và chủ nghĩa duy vật lịch sử Nhận thức được thực chất giá trị, bản chất khoa học, cách mạng của triết học Mác – Lênin; Nhận thức được triết học Mác – Lênin là cơ sở lý luận khoa học của công cuộc xây dựng chủ nghĩa xã hội ở Việt Nam; Liên hệ thực tế những vấn đề có liên quan đến môn triết học Mác – Lênin; Xây dựng thế giới quan duy vật, phương pháp luận biện chứng duy vật làm nền tảng lý luận cho việc nhận thức các vấn đề, nội dung của các môn học khác; Xây dựng niềm tin lý tưởng cách mạng, vận dụng sáng tạo triết học Mác – Lênin trong hoạt động nhận thức và thực tiễn, đáp ứng yêu cầu của con người Việt Nam trong thời kỳ mới; Rèn luyện kỹ năng làm việc nhóm, kỹ năng thuyết trình, nâng cao tư duy phản biện, biết phát hiện và xử lý những vấn đề nảy sinh trong cuộc sống.', 45, 0, 0, 45, 0, 4, 0, 0, 45, 4.26, 'Marxist-Leninist Philosophy', 3, -7192624147616512326, 0, 0, 0, 0, 0, 0);
INSERT INTO `daotao_hocphan` VALUES (2, '180051', 'Kinh tế chính trị Mác - Lênin', '2025-05-31 09:33:12.384043', '2025-07-23 03:09:52.364208', '', 30, 0, 0, 30, 0, 4, 0, 0, 30, 2.84, 'Marxist-Leninist Political Economy', 2, -8358268071150277930, 0, 0, 0, 0, 0, 0);
