INSERT INTO `daotao_lichsuthaydoictdt` VALUES (1, '2025-07-25 09:26:52.234967', 'Cập nhật', '- Thay đổi \'Tên chương trình đào tạo (Tiếng Việt)\' từ \'Y khoa (Phiên bản 1.0.1)\' thành \'Y khoa (Phiên bản 1.0.2)\'', 108, 1);
INSERT INTO `daotao_muctieudaotao` VALUES (1, 'PLO1', 'Có kiến thức cơ bản về lĩnh vực khoa học xã hội, khoa học chính trị, pháp luật, công nghệ thông tin, ngoại ngữ; về lập kế hoạch, tổ chức, giám sát, quản lý, và điều hành hoạt động chuyên môn trong lĩnh vực xét nghiệm.', '2025-05-31 05:19:45.298949', '2025-05-31 05:19:45.298949', 2);
INSERT INTO `daotao_muctieudaotao` VALUES (2, 'PLO2', 'Có khả năng áp dụng kiến thức y học cơ sở vào hoạt động chuyên môn ngành xét nghiệm, phục vụ yêu cầu chẩn đoán và điều trị bệnh.', '2025-05-31 05:19:45.299979', '2025-05-31 05:19:45.299979', 2);
INSERT INTO `daotao_muctieudaotao` VALUES (3, 'PLO3', 'Có khả năng tự học tập, sáng tạo từ đó có khả năng làm việc độc lập hoặc làm việc theo nhóm trong điều kiện làm việc thay đổi, chịu trách nhiệm cá nhân và trách nhiệm đối với nhóm; có khả năng hướng dẫn, giám sát những người khác thực hiện nhiệm vụ xác định.', '2025-05-31 05:19:45.300992', '2025-05-31 05:19:45.300992', 2);
INSERT INTO `daotao_muctieudaotao` VALUES (4, 'PLO4', 'Có khả năng phản biện, phê phán; đánh giá chất lượng công việc sau khi hoàn thành và kết quả thực hiện của các thành viên trong nhóm; truyền đạt vấn đề và giải pháp tới người khác tại nơi làm việc; và chuyển tải, phổ biến kiến thức, kỹ năng trong việc thực hiện những nhiệm vụ cụ thể hoặc phức tạp.', '2025-05-31 05:19:45.301960', '2025-05-31 05:19:45.301960', 2);
INSERT INTO `daotao_muctieudaotao` VALUES (5, 'PLO5', 'Có các kỹ năng cần thiết để có thể giải quyết các vấn đề phức tạp; lập kế hoạch, điều phối, tổ chức, quản lý các nguồn lực, đánh giá và cải thiện hiệu quả các hoạt động; tự định hướng, đưa ra kết luận chuyên môn và có thể bảo vệ được quan điểm cá nhân; dẫn dắt, khởi nghiệp, tạo việc làm cho mình và cho người khác.', '2025-05-31 05:19:45.301960', '2025-05-31 05:19:45.301960', 2);
INSERT INTO `daotao_muctieudaotao` VALUES (6, 'PLO6', 'Có kiến thức chuyên môn và năng lực thực hành vững chắc; có khả năng tham gia vào quản lý, điều hành, giám sát các hoạt động chuyên ngành; có sáng kiến cải tiến chất lượng kỹ thuật nhằm nâng cao chất lượng xét nghiệm và phát triển nghề nghiệp.', '2025-05-31 05:19:45.302991', '2025-05-31 05:19:45.302991', 2);
INSERT INTO `daotao_muctieudaotao` VALUES (7, 'PLO7', 'Có phẩm chất đạo đức nghề nghiệp, tinh thần trách nhiệm cao, tác phong làm việc thận trọng, chân thành hợp tác với đồng nghiệp; có khả năng tự học và tham gia nghiên cứu khoa học đáp ứng nhu cầu bảo vệ, chăm sóc và nâng cao sức khỏe nhân dân.', '2025-05-31 05:19:45.303949', '2025-05-31 05:19:45.303949', 2);
INSERT INTO `daotao_muctieudaotao` VALUES (8, 'PO1', 'Có kiến thức cơ bản về y học cơ sở, y tế công cộng, tổ chức quản lý y tế, khoa học xã hội, khoa học chính trị, pháp luật, công nghệ thông tin, ngoại ngữ; về lập kế hoạch, tổ chức, giám sát, quản lý, và điều hành hoạt động chuyên môn trong lĩnh vực Y tế công cộng.', '2025-07-23 06:06:10.138473', '2025-07-23 06:29:54.168987', 106);
INSERT INTO `daotao_muctieudaotao` VALUES (9, 'PO2', 'Có khả năng áp dụng kiến thức kỹ thuật cơ sở về Y tế công cộng vào hoạt động chuyên môn.', '2025-07-23 06:06:40.069067', '2025-07-23 06:06:40.069067', 106);
INSERT INTO `daotao_muctieudaotao` VALUES (10, 'PO3', 'Có khả năng làm việc độc lập hoặc làm việc theo nhóm trong điều kiện làm việc thay đổi, chịu trách nhiệm cá nhân và trách nhiệm đối với nhóm; có khả năng hướng dẫn, giám sát những người khác thực hiện nhiệm vụ xác định.', '2025-07-23 06:39:34.826097', '2025-07-23 06:39:34.826097', 106);
